<?php
namespace App\Filament\Resources;
use App\Models\Faq; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class FaqResource extends Resource { protected static ?string $model=Faq::class; protected static ?string $navigationGroup='Content'; protected static ?string $navigationIcon='heroicon-o-question-mark-circle'; public static function canViewAny():bool{return auth()->user()?->can('content.manage')??false;} public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('service_id')->relationship('service','name_en'),Forms\Components\TextInput::make('category'),Forms\Components\TextInput::make('question_en')->required(),Forms\Components\TextInput::make('question_ar')->required(),Forms\Components\RichEditor::make('answer_en')->required(),Forms\Components\RichEditor::make('answer_ar')->required(),Forms\Components\TextInput::make('sort_order')->numeric()->default(0),Forms\Components\Toggle::make('published')->default(true),Forms\Components\Toggle::make('featured')]);} public static function table(Table $table):Table{return $table->defaultSort('sort_order')->columns([Tables\Columns\TextColumn::make('question_en')->searchable(),Tables\Columns\TextColumn::make('service.name_en'),Tables\Columns\IconColumn::make('published')->boolean(),Tables\Columns\IconColumn::make('featured')->boolean(),Tables\Columns\TextColumn::make('sort_order')->sortable()])->filters([Tables\Filters\TernaryFilter::make('published'),Tables\Filters\TernaryFilter::make('featured')])->reorderable('sort_order')->actions([Tables\Actions\EditAction::make()])->bulkActions([Tables\Actions\DeleteBulkAction::make()]);} public static function getPages():array{return ['index'=>Pages\ListFaqs::route('/'),'create'=>Pages\CreateFaq::route('/create'),'view'=>Pages\ViewFaq::route('/{record}'),'edit'=>Pages\EditFaq::route('/{record}/edit')];} }
